create table public.football_feature_pool_snapshot (id boolean primary key default true check(id),payload jsonb not null,generated_at timestamptz not null,build_ms integer not null default 0); alter table public.football_feature_pool_snapshot enable row level security; revoke all on public.football_feature_pool_snapshot from anon,authenticated; grant all on public.football_feature_pool_snapshot to service_role; create function public.publish_football_feature_pool(p_payload jsonb,p_started_at timestamptz,p_build_ms integer) returns boolean language plpgsql security invoker set search_path=public as $$ begin insert into football_feature_pool_snapshot(id,payload,generated_at,build_ms) values(true,p_payload,p_started_at,p_build_ms) on conflict(id) do update set payload=excluded.payload,generated_at=excluded.generated_at,build_ms=excluded.build_ms where football_feature_pool_snapshot.generated_at<excluded.generated_at; return found; end $$; revoke all on function public.publish_football_feature_pool(jsonb,timestamptz,integer) from public,anon,authenticated; grant execute on function public.publish_football_feature_pool(jsonb,timestamptz,integer) to service_role; select cron.alter_job((select jobid from cron.job where jobname='football-feature-push-sync'),schedule:='*/2 * * * *');;
